<div class="table-responsive directory-table-scroll"><table class="table table-hover align-middle mb-0"><thead><tr><th scope="col">System ID</th><?php if($kind==='polling_station'): ?><th scope="col">Polling station ID</th><?php endif; ?><th scope="col">Location</th><?php if($kind!=='region'): ?><th scope="col">Hierarchy</th><?php endif; ?><?php if($kind==='polling_station'): ?><th scope="col">Branch assignment</th><?php endif; ?><th scope="col">Linked people</th><th scope="col" class="text-end directory-actions-cell">Action</th></tr></thead><tbody>
<?php foreach($rows as $item): ?><tr><td><span class="location-id">#<?= e($item['id']) ?></span></td><?php if($kind==='polling_station'): ?><td><span class="location-id"><?= e($item['station_code']??'Not recorded') ?></span></td><?php endif; ?><td><strong class="d-block"><?= e($item['name']) ?></strong><?php if($hasShortname): ?><span class="location-shortname"><?= e($item['shortname']) ?></span><?php endif; ?><?php if($kind==='region'): ?><div class="directory-row-links"><a href="<?= e(url('locations',['type'=>'constituency','region_filter'=>$item['id']])) ?>">Constituencies <i class="bi bi-arrow-right" aria-hidden="true"></i></a></div><?php elseif($kind==='constituency'): ?><div class="directory-row-links"><a href="<?= e(url('locations',['type'=>'electoral_area','constituency_filter'=>$item['id']])) ?>">Branches</a><a href="<?= e(url('locations',['type'=>'polling_station','constituency_filter'=>$item['id']])) ?>">Polling stations</a></div><?php elseif($kind==='electoral_area'): ?><div class="directory-row-links"><a href="<?= e(url('locations',['type'=>'polling_station','branch_filter'=>$item['id']])) ?>">Assigned stations <i class="bi bi-arrow-right" aria-hidden="true"></i></a></div><?php endif; ?></td>
<?php if($kind!=='region'): ?><td><span class="d-block"><?= e($item['constituency_name']??$item['region_name']) ?></span><?php if(isset($item['constituency_name'])): ?><small class="text-secondary"><?= e($item['region_name']) ?></small><?php endif; ?></td><?php endif; ?>
<?php if($kind==='polling_station'): ?><td><form method="post" action="<?= e($formUrl) ?>" class="location-assignment"><?= csrf() ?><input type="hidden" name="_action" value="location_save"><input type="hidden" name="kind" value="assignment"><input type="hidden" name="station_id" value="<?= e($item['id']) ?>"><input type="hidden" name="version" value="<?= e($item['updated_at']) ?>"><label class="visually-hidden" for="station-branch-<?= e($item['id']) ?>">Branch for <?= e($item['name']) ?></label><select id="station-branch-<?= e($item['id']) ?>" name="branch_id" class="form-select form-select-sm"><option value="">Branch not assigned</option><?php foreach($branches as $branch): if((int)$branch['constituency_id']!==(int)$item['constituency_id']){continue;} ?><option value="<?= e($branch['id']) ?>" <?= (int)$branch['id']===(int)$item['electoral_area_id']?'selected':'' ?>><?= e($branch['name']) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-primary">Save</button></form><?php if(!$item['electoral_area_id']): ?><small class="text-secondary">Can be assigned later</small><?php endif; ?></td><?php endif; ?>
<?php $usageKey=match($kind){'region'=>'electoral_region_filter','constituency'=>'constituency_filter','electoral_area'=>'branch_filter',default=>'polling_station_filter'}; ?><td><div class="directory-count-links"><a href="<?= e(url('voters',[$usageKey=>$item['id']])) ?>"><strong><?= number($item['voter_count']) ?></strong> voters</a><a href="<?= e(url('members',[$usageKey=>$item['id']])) ?>"><strong><?= number($item['member_count']) ?></strong> members</a></div></td><td class="text-end directory-actions-cell"><a class="btn btn-sm btn-light" href="<?= e(url('locations',array_replace($filters,['edit'=>$item['id']])).'#location-editor') ?>" aria-label="Edit <?= e($item['name']) ?>"><i class="bi bi-pencil me-1" aria-hidden="true"></i>Edit</a></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="<?= $kind==='polling_station'?7:($kind==='region'?4:5) ?>"><div class="location-empty"><i class="bi bi-geo-alt" aria-hidden="true"></i><h3>No <?= e($singular[$kind]) ?> records found</h3><p class="mb-0">Adjust your filters or add a <?= e($singular[$kind]) ?> using the form.</p></div></td></tr><?php endif; ?></tbody></table></div>
